//! Scripts: one `id {json}` per line; blank lines and `#` comments are passed over.

use crate::json::Value;

pub struct Line {
    pub line: usize,
    pub id: String,
    pub params: Value,
}

/// Parses a whole script before anything runs, so a bad line stops it at once.
pub fn parse(text: &str) -> Result<Vec<Line>, String> {
    let mut out = Vec::new();
    for (n, raw) in text.lines().enumerate() {
        let t = raw.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        let (id, rest) = match t.find(char::is_whitespace) {
            Some(i) => (&t[..i], t[i..].trim()),
            None => (t, ""),
        };
        let params = if rest.is_empty() {
            Value::obj()
        } else {
            match crate::json::parse(rest) {
                Ok(v) => v,
                Err(e) => return Err(format!("line {}: bad JSON after `{}`: {}", n + 1, id, e)),
            }
        };
        out.push(Line { line: n + 1, id: id.to_string(), params });
    }
    Ok(out)
}
//! A session: the project, its file, and its undo history; commands run here.

use crate::json::Value;
use crate::project::Project;

pub struct Step {
    pub before: Project,
    pub after: Project,
    pub label: String,
}

pub struct Session {
    pub project: Project,
    pub path: Option<String>,
    pub undo: Vec<Step>,
    pub redo: Vec<Step>,
    pub read_only: bool,
    /// The phase and design option this session makes elements in.
    pub now_phase: Option<String>,
    pub now_option: Option<String>,
}

pub const MAX_UNDO: usize = 200;

impl Session {
    pub fn new() -> Session {
        Session {
            project: Project::new("en"),
            path: None,
            undo: Vec::new(),
            redo: Vec::new(),
            read_only: false,
            now_phase: None,
            now_option: None,
        }
    }

    /// Runs a command by id (or alias, any case) with its parameters.
    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
        let Some((cid, label)) = crate::commands::resolve(id) else {
            return Err(format!("unknown command `{}`; list_commands shows them", id));
        };
        let before = self.project.clone();
        // the phase and option this session makes elements in go back with a refused command
        let now_before = (self.now_phase.clone(), self.now_option.clone());
        let res = crate::commands::run(self, &cid, params);
        match res {
            Ok(out) => {
                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
                    // a scan nothing places any more goes with the command that left it so
                    crate::cloud::drop_unplaced(&mut self.project);
                    if let Err(e) = crate::check::check(&self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
                        if self.undo.len() > MAX_UNDO {
                            self.undo.remove(0);
                        }
                        self.redo.clear();
                    }
                }
                Ok(out)
            }
            Err(e) => {
                self.project = before;
                (self.now_phase, self.now_option) = now_before;
                Err(e)
            }
        }
    }

    pub fn history(&self) -> Vec<String> {
        self.undo.iter().map(|s| s.label.clone()).collect()
    }
}
//! Common lookups on the model: levels, elements by id or GUID.

use crate::json::Value;
use crate::project::Project;

/// Levels from the lowest up (ties by id).
pub fn levels(pr: &Project) -> Vec<u64> {
    crate::commands::basic::level_ids_sorted(pr)
}

pub fn elev(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

pub fn name(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The lowest level, where commands go without one.
pub fn default_level(pr: &Project) -> Option<u64> {
    levels(pr).first().copied()
}

/// The next level up from one, if any.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let ls = levels(pr);
    let i = ls.iter().position(|l| *l == level)?;
    ls.get(i + 1).copied()
}

/// An element by its id (a number or a string of one) or its GUID.
pub fn find(pr: &Project, v: &Value) -> Option<u64> {
    match v {
        Value::Num(_) => {
            let id = crate::commands::params::id_of(v)?;
            if pr.elements.contains_key(&id) {
                Some(id)
            } else {
                None
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return if pr.elements.contains_key(&id) { Some(id) } else { None };
            }
            let g = normalize_guid(t)?;
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A GUID as the model keeps it (lowercase, hyphenated), from one with or without braces and dashes.
pub fn normalize_guid(s: &str) -> Option<String> {
    let t = s.trim().trim_start_matches('{').trim_end_matches('}');
    let hex: String = t.chars().filter(|c| *c != '-').collect();
    if hex.len() != 32 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let h = hex.to_lowercase();
    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
}

/// A level (or a plan view, whose level it is) given by name, id or GUID.
pub fn resolve_level(pr: &Project, cmd: &str, key: &str, v: &Value) -> Result<u64, String> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = find(pr, v).ok_or_else(not)?;
            level_of_view(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            if let Some(id) = find(pr, v) {
                return level_of_view(pr, id).ok_or_else(not);
            }
            if s.trim().parse::<u64>().is_ok() || normalize_guid(s).is_some() {
                return Err(not());
            }
            for id in levels(pr) {
                if name(pr, id) == *s {
                    return Ok(id);
                }
            }
            for id in pr.ids_of("planview") {
                if name(pr, id) == *s {
                    if let Some(l) = level_of_view(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = levels(pr).iter().map(|l| name(pr, *l)).collect();
            Err(format!(
                "{}: no level or plan view named `{}` (the levels are: {})",
                cmd,
                s,
                names.join(", ")
            ))
        }
        _ => Err(not()),
    }
}

/// The level of a level, or of a plan view.
pub fn level_of_view(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A level from the params' `key`, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> Result<u64, String> {
    match crate::commands::params::get(p, key) {
        Some(v) => resolve_level(pr, cmd, key, v),
        None => default_level(pr).ok_or_else(|| format!("{}: the project has no level", cmd)),
    }
}
//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    core_check(pr)?;
    crate::cloud::check(pr)?;
    crate::media::check(pr)?;
    crate::styles::check(pr)?;
    crate::arch::check(pr)?;
    crate::structure::check(pr)?;
    crate::views::check(pr)?;
    crate::edit::check(pr)?;
    crate::readers::check(pr)?;
    Ok(())
}

fn core_check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}
//! Reading the model: `inspect` and `elements`.

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    let mut counts = Map::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
        counts.insert(&c, Value::u(n + 1));
    }
    m.insert("counts", Value::Obj(counts));
    m.insert("history", s.history().into());
    m.insert("language", pr.language().into());
    m.insert("name", pr.name().into());
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    m.insert("levels", Value::Arr(levels));
    for (k, v) in crate::styles::inspect_entries(s) {
        m.insert(&k, v);
    }
    Value::Obj(m)
}

pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        if let Some(want) = &cat {
            if c != want {
                continue;
            }
        }
        let mut x = e.clone();
        x.set("id", Value::u(*id));
        if c == "level" {
            x.set("computation_height", Value::f(1200.0));
        }
        if c == "pointcloud" {
            crate::cloud::element_view(pr, &mut x);
        }
        out.push(x);
    }
    let n = out.len();
    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
}

//! `bimcraft-cli`: BIMCraft from the command line. Scripts, conversion, and an MCP server for
//! agents, all through the same commands.

mod mcp;
mod revit;
mod window;

use std::io::Write;
use std::process::ExitCode;

use bimcraft_core::cad::DwgReader;
use bimcraft_core::engine::{Session, catalog};
use bimcraft_core::sample::SAMPLE;
use serde_json::{Value, json};

const USAGE: &str = "USAGE:
  bimcraft-cli run [FILE] [--sample | --highrise] [--cmd 'ID {json}']… [--script FILE]… [--save PATH]…
      Open FILE (a .bimcraft project, or an .ifc or Revit .rvt file to import) or start empty, then in order: build the sample house, run
      commands and scripts (one `ID {json}` per line), save. --save writes by extension:
      .bimcraft (the project), .ifc (IFC4), .glb (the 3D view's scene as glTF), .svg or .png (the lowest level's plan).
      --highrise builds an original 20-storey performance sample (about 10,000 elements).
  bimcraft-cli info FILE         levels, element counts, types and warnings of a project or an IFC file; of a Revit .rvt or
                                 .rfa file, its release, last save, levels and element counts by category
  bimcraft-cli convert IN OUT    a project, an IFC file or a Revit .rvt file to .ifc, .glb, .svg, .png or .bimcraft
  bimcraft-cli commands          every command and its parameters
  bimcraft-cli mcp [--read-only] [FILE | --connect [PORT]]
                                 an MCP server on stdio, for agents: on a headless project of its own (FILE, opened first, or an
                                 empty one), or with --connect on the project open in a window whose control port is open
                                 (`bimcraft --control PORT` or File > Settings > Agents; without PORT, the last one). With
                                 --read-only the agent may read the project, never change it or write over its file
  bimcraft-cli --version         the release";

fn print(out: &mut impl Write, v: &Value) -> Result<(), String> {
    writeln!(out, "{v}").map_err(|e| format!("stdout: {e}"))
}

fn print_pretty(out: &mut impl Write, v: &Value) -> Result<(), String> {
    writeln!(out, "{}", serde_json::to_string_pretty(v).unwrap_or_default()).map_err(|e| format!("stdout: {e}"))
}

fn cli(args: &[String], out: &mut impl Write) -> Result<(), String> {
    let mut s = Session::new();
    s.dwg = dwg_reader();
    match args {
        [cmd, rest @ ..] if cmd == "run" => {
            let mut rest = rest.iter();
            while let Some(arg) = rest.next() {
                let mut value = || rest.next().ok_or_else(|| format!("{arg} needs a value\n\n{USAGE}"));
                let results = match arg.as_str() {
                    "--sample" => s.script(SAMPLE).map(|_| Vec::new())?,
                    "--highrise" => vec![s.execute("highrise", &json!({}))?],
                    "--cmd" => s.script(value()?)?,
                    "--script" => {
                        let path = value()?;
                        s.script(&std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?)?
                    }
                    "--save" => vec![s.execute("save", &json!({ "path": value()? }))?],
                    flag if flag.starts_with("--") => return Err(format!("unknown option `{flag}`\n\n{USAGE}")),
                    file if revit::is_revit(file) => vec![revit::open(&mut s, file)?],
                    file => vec![s.execute("open", &json!({ "path": file }))?],
                };
                for r in results.iter().filter(|r| !r.is_null()) {
                    print(out, r)?;
                }
            }
            Ok(())
        }
        [cmd, file] if cmd == "info" && revit::is_revit(file) => print_pretty(out, &revit::info(file)?),
        [cmd, file] if cmd == "info" => {
            s.execute("open", &json!({ "path": file }))?;
            print_pretty(out, &s.execute("inspect", &json!({}))?)
        }
        [cmd, from, to] if cmd == "convert" => {
            if revit::is_revit(from) {
                revit::open(&mut s, from)?;
            } else {
                s.execute("open", &json!({ "path": from }))?;
            }
            print(out, &s.execute("save", &json!({ "path": to }))?)
        }
        [cmd] if cmd == "commands" => print_pretty(out, &catalog()),
        [flag] if flag == "--version" || flag == "-V" => {
            writeln!(out, "bimcraft-cli {}", env!("CARGO_PKG_VERSION")).map_err(|e| format!("stdout: {e}"))
        }
        _ => Err(USAGE.into()),
    }
}

/// What follows `mcp`.
#[derive(Debug, Default, PartialEq)]
struct McpArgs {
    /// `--connect`, with a port or without: none inside is a window, whichever the bridge file names.
    connect: Option<Option<u16>>,
    /// `--read-only`: the agent may read the project and never change it.
    read_only: bool,
    /// The project a headless server opens before it answers.
    file: Option<String>,
}

const MCP_USAGE: &str = "usage: bimcraft-cli mcp [--read-only] [FILE | --connect [PORT]]";

fn mcp_args(args: &[String]) -> Result<McpArgs, String> {
    let mut a = McpArgs::default();
    let mut rest = args.iter().peekable();
    while let Some(arg) = rest.next() {
        match arg.as_str() {
            "--read-only" => a.read_only = true,
            "--connect" if a.connect.is_none() => {
                let port = rest.next_if(|p| !p.starts_with("--"));
                a.connect = Some(port.map(|p| p.parse().map_err(|_| format!("`{p}` is not a port: a number up to 65535"))).transpose()?);
            }
            flag if flag.starts_with('-') => return Err(format!("`{flag}`: {MCP_USAGE}")),
            file if a.file.is_none() => a.file = Some(file.to_string()),
            _ => return Err(MCP_USAGE.into()),
        }
    }
    if a.connect.is_some() && a.file.is_some() {
        return Err(format!("a window has its own project: --connect takes no FILE ({MCP_USAGE})"));
    }
    Ok(a)
}

/// The MCP server `args` asks for: attached to a window, or on a session of its own with its file open, and read-only when asked.
fn mcp_server(args: McpArgs) -> Result<mcp::Server, String> {
    let mut server = match args.connect {
        Some(port) => mcp::Server::attached(window::Window::connect(port)?),
        None => mcp::Server::new(),
    };
    if let Some(file) = &args.file {
        server.open(file)?;
    }
    if args.read_only {
        server.read_only();
    }
    Ok(server)
}

/// The DWG reader a session is given: `bimcraft-dwg`'s, which reads a drawing in a child process of this program, behind the
/// `dwg` feature. A build without it hands none, and a DWG says to save it as DXF.
#[cfg(feature = "dwg")]
fn dwg_reader() -> Option<DwgReader> {
    bimcraft_dwg::reader()
}

#[cfg(not(feature = "dwg"))]
fn dwg_reader() -> Option<DwgReader> {
    None
}

/// What this program does when it's started as the child that reads a DWG (`bimcraft_dwg::CHILD_ARG`): none when it isn't.
#[cfg(feature = "dwg")]
fn dwg_child(args: &[String]) -> Option<ExitCode> {
    bimcraft_dwg::child_main(args)
}

#[cfg(not(feature = "dwg"))]
fn dwg_child(_: &[String]) -> Option<ExitCode> {
    None
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if let Some(code) = dwg_child(&args) {
        return code;
    }
    if args.first().is_some_and(|a| a == "mcp") {
        let mut server = match mcp_args(&args[1..]).and_then(mcp_server) {
            Ok(server) => server,
            Err(e) => {
                eprintln!("bimcraft-cli mcp: {e}");
                return ExitCode::FAILURE;
            }
        };
        return match server.serve(std::io::stdin().lock(), std::io::stdout().lock()) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("bimcraft-cli mcp: {e}");
                ExitCode::FAILURE
            }
        };
    }
    match cli(&args, &mut std::io::stdout().lock()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("{e}");
            ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    fn cli_out(args: &[&str]) -> Result<String, String> {
        let args: Vec<String> = args.iter().map(|s| s.to_string()).collect();
        let mut out = Vec::new();
        cli(&args, &mut out).map(|()| String::from_utf8(out).unwrap())
    }

    #[test]
    fn mcp_is_headless_on_a_file_or_none_or_connects_to_a_window_and_may_only_read_either() {
        let args = |text: &str| text.split_whitespace().map(String::from).collect::<Vec<_>>();
        let mcp = |connect, read_only, file: Option<&str>| Ok(McpArgs { connect, read_only, file: file.map(String::from) });
        assert_eq!(mcp_args(&args("")), mcp(None, false, None));
        assert_eq!(mcp_args(&args("--connect")), mcp(Some(None), false, None));
        assert_eq!(mcp_args(&args("--connect 7000")), mcp(Some(Some(7000)), false, None));
        assert_eq!(mcp_args(&args("--read-only house.bimcraft")), mcp(None, true, Some("house.bimcraft")));
        assert_eq!(mcp_args(&args("house.ifc --read-only")), mcp(None, true, Some("house.ifc")));
        assert_eq!(mcp_args(&args("--connect --read-only")), mcp(Some(None), true, None));
        assert_eq!(mcp_args(&args("--read-only --connect 7000")), mcp(Some(Some(7000)), true, None));
        for bad in ["--connect x", "--connect 70000", "--connect 1 2", "--attach", "a.bimcraft b.bimcraft", "--connect 7000 --connect"] {
            assert!(mcp_args(&args(bad)).is_err(), "{bad}");
        }
    }

    #[test]
    fn a_read_only_mcp_server_starts_on_the_file_it_is_given_and_a_file_that_is_not_there_stops_it() {
        let dir = std::env::temp_dir().join(format!("bimcraft-cli-mcp-file-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("house.bimcraft");
        let mut s = Session::new();
        s.execute("wall", &json!({"points": [[0, 0], [4000, 0]]})).unwrap();
        s.execute("save", &json!({"path": file})).unwrap();
        let given = McpArgs { connect: None, read_only: true, file: Some(file.to_string_lossy().into_owned()) };
        let mut server = mcp_server(given).unwrap();
        let line = json!({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": "inspect_model", "arguments": {}}});
        let reply: Value = serde_json::from_str(&server.handle_line(&line.to_string()).unwrap()).unwrap();
        assert!(reply["result"]["content"][0]["text"].as_str().unwrap().contains("\"wall\": 1"), "{reply}");
        let missing = McpArgs { connect: None, read_only: true, file: Some(dir.join("gone.bimcraft").to_string_lossy().into_owned()) };
        assert!(mcp_server(missing).is_err());
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn run_builds_the_sample_and_saves_each_format() {
        let base = std::env::temp_dir().join(format!("bimcraft-cli-{}", std::process::id()));
        let path = |ext: &str| base.with_extension(ext).to_string_lossy().into_owned();
        let (project, ifc, png, svg) = (path("bimcraft"), path("ifc"), path("png"), path("svg"));
        let roof = r#"level {"elevation": 3200, "name": "Roof"}"#;
        let out = cli_out(&["run", "--sample", "--cmd", roof, "--save", &project, "--save", &ifc, "--save", &png]).unwrap();
        assert!(out.contains("\"Roof\""), "{out}");
        assert!(std::fs::read(&png).unwrap().starts_with(b"\x89PNG"));
        assert!(std::fs::read_to_string(&ifc).unwrap().contains("IFCWALL("));
        let info: Value = serde_json::from_str(&cli_out(&["info", &project]).unwrap()).unwrap();
        assert_eq!(info["counts"]["room"], 4);
        assert_eq!(info["levels"][2]["name"], "Roof", "levels sort by elevation");
        cli_out(&["convert", &project, &svg]).unwrap();
        assert!(std::fs::read_to_string(&svg).unwrap().starts_with("<svg"));
        for p in [project, ifc, png, svg] {
            let _ = std::fs::remove_file(p);
        }
    }

    #[test]
    fn highrise_option_builds_the_shareable_performance_fixture() {
        let out = cli_out(&["run", "--highrise", "--cmd", "inspect {}"]).unwrap();
        let reply: Value = serde_json::from_str(out.lines().next().unwrap()).unwrap();
        assert_eq!(reply["storeys"], 20);
        assert_eq!(reply["elements"], 9521);
        let info: Value = serde_json::from_str(out.lines().last().unwrap()).unwrap();
        assert_eq!(info["counts"]["level"], 21);
        assert_eq!(info["counts"]["beam"], 2200);
    }

    #[test]
    fn bad_usage_and_failing_commands_are_errors() {
        assert!(cli_out(&[]).unwrap_err().contains("USAGE"));
        assert!(cli_out(&["run", "--frobnicate"]).unwrap_err().contains("--frobnicate"));
        assert!(cli_out(&["run", "--save"]).unwrap_err().contains("needs"));
        assert!(cli_out(&["run", "--cmd", r#"door {"at": [0, 0]}"#]).unwrap_err().contains("no wall"));
        assert!(cli_out(&["commands"]).unwrap().contains("\"wall\""));
    }

