  8	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
  9	    match cid {
 10	        "new" => cmd_new(s, p),
 11	        "open" => {
 12	            let path = match opt_text(p, "open", "path")? {
 13	                Some(x) => x,
 14	                None => return Err("open: `path` is required".into()),
 15	            };
 16	            // the script's `open` reads a project file whatever its extension: a Revit file is
 17	            // imported only by `run x.rvt`, `convert` and the MCP server's `open`
 18	            open_project_file(s, &path).map_err(|e| format!("open: {}", e))
 19	        }
 20	        "save" => cmd_save(s, p),
 21	        "undo" => cmd_undo(s, p, true),
 22	        "redo" => cmd_undo(s, p, false),
 23	        "level" => cmd_level(s, p),
 24	        "grid" => cmd_grid(s, p),
 25	        "delete" => cmd_delete(s, p),
 26	        "inspect" => Ok(crate::inspect::inspect(s)),
 27	        "elements" => crate::inspect::elements(s, p),
 28	        _ => Err(format!("{}: not supported here", cid)),
 29	    }
 30	}
