 34	fn cmd_new(s: &mut Session, p: &Value) -> R<Value> {
 35	    let name = opt_text(p, "new", "name")?;
 36	    let lang = opt_text(p, "new", "language")?.unwrap_or_else(|| "en".into()).to_lowercase();
 37	    if !crate::project::LANGS.contains(&lang.as_str()) {
 38	        return Err(format!("new: `{}` is no language here; use en, pt, es or sv", lang));
 39	    }
 40	    let mut proj = Project::new(&lang);
 41	    if let Some(n) = name {
 42	        proj.doc.insert("name", Value::Str(n));
 43	    }
 44	    s.project = proj;
 45	    s.now_phase = None;
 46	    s.now_option = None;
 47	    s.path = None;
 48	    s.undo.clear();
 49	    s.redo.clear();
 50	    Ok(jobj! {"language" => lang, "name" => s.project.name()})
 51	}
