 63	/// Opens a project file (or an IFC file), whatever the extension says otherwise.
 64	pub fn open_project_file(s: &mut Session, path: &str) -> Result<Value, String> {
 65	    let low = path.to_lowercase();
 66	    if low.ends_with(".ifc") {
 67	        return crate::ifc::import::import(s, path);
 68	    }
 69	    let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {}", path, e))?;
 70	    let v = crate::json::parse(&text).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
 71	    let proj = crate::load::load(v).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
 72	    // what the file's point clouds place must be there (the original checks its model on opening)
 73	    crate::cloud::check(&proj).map_err(|e| format!("{}: {}", path, e))?;
 74	    s.project = proj;
 75	    s.now_phase = None;
 76	    s.now_option = None;
 77	    s.path = Some(path.to_string());
 78	    s.undo.clear();
 79	    s.redo.clear();
 80	    Ok(jobj! {"name" => s.project.name(), "path" => path})
 81	}
