 83	fn cmd_save(s: &mut Session, p: &Value) -> R<Value> {
 84	    let path = match opt_text(p, "save", "path")? {
 85	        Some(x) => x,
 86	        None => match &s.path {
 87	            Some(x) => x.clone(),
 88	            None => return Err("save: `path` is required: this project hasn't been saved yet".into()),
 89	        },
 90	    };
 91	    let low = path.to_lowercase();
 92	    if low.ends_with(".ifc") {
 93	        let text = crate::ifc::export::export(&s.project, &path);
 94	        std::fs::write(&path, text).map_err(|e| format!("save: {}: {}", path, e))?;
 95	        return Ok(jobj! {"format" => "IFC4", "path" => path});
 96	    }
 97	    let text = s.project.to_file_string();
 98	    write_atomic(&path, text.as_bytes()).map_err(|e| format!("save: {}: {}", path, e))?;
 99	    s.path = Some(path.clone());
100	    Ok(jobj! {"format" => "bimcraft", "path" => path})
101	}
