133	fn cmd_undo(s: &mut Session, p: &Value, undo: bool) -> R<Value> {
134	    let cmd = if undo { "undo" } else { "redo" };
135	    let avail = if undo { s.undo.len() } else { s.redo.len() };
136	    if avail == 0 {
137	        return Err(if undo { "nothing to undo".into() } else { "nothing to redo".into() });
138	    }
139	    let count = match get(p, "count") {
140	        None => 1,
141	        Some(v) => match v.as_f64() {
142	            Some(c) if c >= 1.0 && c <= avail as f64 && c.fract() == 0.0 => c as usize,
143	            _ => {
144	                return Err(format!(
145	                    "`count` must be from 1 to {}, the steps there are to {}",
146	                    avail, cmd
147	                ))
148	            }
149	        },
150	    };
151	    let mut label = String::new();
152	    for _ in 0..count {
153	        if undo {
154	            let step = s.undo.pop().unwrap();
155	            s.project = step.before.clone();
156	            label = step.label.clone();
157	            s.redo.push(step);
158	        } else {
159	            let step = s.redo.pop().unwrap();
160	            s.project = step.after.clone();
161	            label = step.label.clone();
162	            s.undo.push(step);
163	        }
164	    }
165	    let mut m = Map::new();
166	    m.insert("count", Value::u(count as u64));
167	    m.insert(if undo { "undone" } else { "redone" }, Value::Str(label));
168	    Ok(Value::Obj(m))
169	}
