173	pub fn level_ids_sorted(pr: &Project) -> Vec<u64> {
174	    let mut ids = pr.ids_of("level");
175	    ids.sort_by(|a, b| {
176	        let ea = pr.el(*a).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
177	        let eb = pr.el(*b).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
178	        ea.partial_cmp(&eb).unwrap_or(std::cmp::Ordering::Equal).then(a.cmp(b))
179	    });
180	    ids
181	}
