206	            }
207	            Some(pts)
208	        }
209	    };
210	    let pr = &mut s.project;
211	    let name = match name {
212	        Some(n) => n,
213	        None => {
214	            let word = level_word(&pr.language());
215	            let names: Vec<String> = pr
216	                .ids_of("level")
217	                .iter()
218	                .filter_map(|id| pr.el(*id).and_then(|e| e.get("name")).and_then(|n| n.as_str()).map(|s| s.to_string()))
219	                .collect();
