 23	pub const MAX_UNDO: usize = 200;
 24	
 25	impl Session {
 26	    pub fn new() -> Session {
 27	        Session {
 28	            project: Project::new("en"),
 29	            path: None,
 30	            undo: Vec::new(),
 31	            redo: Vec::new(),
 32	            read_only: false,
 33	            now_phase: None,
 34	            now_option: None,
 35	        }
 36	    }
 37	
 38	    /// Runs a command by id (or alias, any case) with its parameters.
 39	    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
 40	        let Some((cid, label)) = crate::commands::resolve(id) else {
 41	            return Err(format!("unknown command `{}`; list_commands shows them", id));
 42	        };
 43	        let before = self.project.clone();
 44	        // the phase and option this session makes elements in go back with a refused command
 45	        let now_before = (self.now_phase.clone(), self.now_option.clone());
 46	        let res = crate::commands::run(self, &cid, params);
 47	        match res {
 48	            Ok(out) => {
 49	                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
 50	                    // a scan nothing places any more goes with the command that left it so
 51	                    crate::cloud::drop_unplaced(&mut self.project);
 52	                    if let Err(e) = crate::check::check(&self.project) {
 53	                        self.project = before;
 54	                        (self.now_phase, self.now_option) = now_before;
 55	                        return Err(e);
 56	                    }
 57	                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
 58	                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
 59	                        if self.undo.len() > MAX_UNDO {
 60	                            self.undo.remove(0);
 61	                        }
 62	                        self.redo.clear();
 63	                    }
 64	                }
 65	                Ok(out)
 66	            }
 67	            Err(e) => {
 68	                self.project = before;
 69	                (self.now_phase, self.now_option) = now_before;
 70	                Err(e)
 71	            }
 72	        }
 73	    }
 74	
 75	    pub fn history(&self) -> Vec<String> {
 76	        self.undo.iter().map(|s| s.label.clone()).collect()
 77	    }
 78	}
