  5	pub fn check(pr: &Project) -> Result<(), String> {
  6	    core_check(pr)?;
  7	    crate::cloud::check(pr)?;
  8	    crate::media::check(pr)?;
  9	    crate::styles::check(pr)?;
 10	    crate::arch::check(pr)?;
 11	    crate::structure::check(pr)?;
 12	    crate::views::check(pr)?;
 13	    crate::edit::check(pr)?;
 14	    crate::readers::check(pr)?;
 15	    Ok(())
 16	}
 17	
 18	fn core_check(pr: &Project) -> Result<(), String> {
 19	    let mut level_names: Vec<String> = Vec::new();
 20	    let mut grid_names: Vec<String> = Vec::new();
 21	    for (id, e) in &pr.elements {
 22	        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
 23	        match cat {
 24	            "level" => {
 25	                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
 26	                if level_names.contains(&name) {
 27	                    return Err(format!("level {}: another level is already named `{}`", id, name));
 28	                }
 29	                level_names.push(name);
 30	                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
 31	                    let a = ext.first().and_then(crate::commands::params::point_of);
 32	                    let b = ext.get(1).and_then(crate::commands::params::point_of);
 33	                    if let (Some(a), Some(b)) = (a, b) {
 34	                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
 35	                            return Err(format!(
 36	                                "level {}: its extent runs from its south-west corner to its north-east one",
 37	                                id
 38	                            ));
 39	                        }
 40	                    }
 41	                }
 42	            }
 43	            "grid" => {
 44	                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
 45	                if grid_names.contains(&name) {
 46	                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
 47	                }
 48	                grid_names.push(name);
 49	                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
 50	                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
 51	                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
 52	                if len <= 1.0 {
 53	                    return Err(format!("grid {}: too short ({} mm)", id, len));
 54	                }
 55	            }
 56	            _ => {}
 57	        }
 58	    }
 59	    Ok(())
 60	}
