  3	use crate::json::{Map, Value};
  4	use crate::session::Session;
  5	
  6	pub fn inspect(s: &Session) -> Value {
  7	    let pr = &s.project;
  8	    let mut m = Map::new();
  9	    let mut counts = Map::new();
 10	    for e in pr.elements.values() {
 11	        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
 12	        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
 13	        counts.insert(&c, Value::u(n + 1));
 14	    }
 15	    m.insert("counts", Value::Obj(counts));
 16	    m.insert("history", s.history().into());
 17	    m.insert("language", pr.language().into());
 18	    m.insert("name", pr.name().into());
 19	    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
 20	        .iter()
 21	        .map(|id| {
 22	            let e = pr.el(*id).unwrap();
 23	            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
 24	        })
 25	        .collect();
 26	    m.insert("levels", Value::Arr(levels));
 27	    for (k, v) in crate::styles::inspect_entries(s) {
 28	        m.insert(&k, v);
 29	    }
 30	    Value::Obj(m)
 31	}
