   103	/// Writes a file as tempfile and persist do: a hidden file beside it, renamed over it.
   104	pub fn write_atomic(path: &str, bytes: &[u8]) -> Result<(), String> {
   105	    use std::io::Write;
   106	    use std::os::unix::fs::OpenOptionsExt;
   107	    let p = std::path::Path::new(path);
   108	    let parent = match p.parent() {
   109	        Some(d) if !d.as_os_str().is_empty() => d.to_path_buf(),
   110	        _ => std::path::PathBuf::from(""),
   111	    };
   112	    let dir = if parent.is_absolute() {
   113	        parent
   114	    } else {
   115	        std::env::current_dir().map_err(|e| e.to_string())?.join(parent)
   116	    };
   117	    let tmp = dir.join(format!(".tmp{}", crate::rand::alnum(6)));
   118	    let mut f = std::fs::OpenOptions::new()
   119	        .write(true)
   120	        .create_new(true)
   121	        .mode(0o600)
   122	        .open(&tmp)
   123	        .map_err(|e| format!("{} at path {:?}", e, tmp.to_string_lossy()))?;
   124	    f.write_all(bytes).map_err(|e| format!("{} at path {:?}", e, tmp.to_string_lossy()))?;
   125	    drop(f);
   126	    std::fs::rename(&tmp, p).map_err(|e| {
   127	        let _ = std::fs::remove_file(&tmp);
   128	        format!("{} at path {:?}", e, tmp.to_string_lossy())
   129	    })?;
   130	    Ok(())
   131	}
