     6	pub struct Step {
     7	    pub before: Project,
     8	    pub after: Project,
     9	    pub label: String,
    10	}
    11	
    12	pub struct Session {
    13	    pub project: Project,
    14	    pub path: Option<String>,
    15	    pub undo: Vec<Step>,
    16	    pub redo: Vec<Step>,
    17	    pub read_only: bool,
    18	    /// The phase and design option this session makes elements in.
    19	    pub now_phase: Option<String>,
    20	    pub now_option: Option<String>,
    21	}
