     5	
     6	pub fn inspect(s: &Session) -> Value {
     7	    let pr = &s.project;
     8	    let mut m = Map::new();
     9	    let mut counts = Map::new();
    10	    for e in pr.elements.values() {
    11	        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
    12	        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
    13	        counts.insert(&c, Value::u(n + 1));
    14	    }
    15	    m.insert("counts", Value::Obj(counts));
    16	    m.insert("history", s.history().into());
    17	    m.insert("language", pr.language().into());
    18	    m.insert("name", pr.name().into());
    19	    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
    20	        .iter()
    21	        .map(|id| {
    22	            let e = pr.el(*id).unwrap();
    23	            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
    24	        })
    25	        .collect();
    26	    m.insert("levels", Value::Arr(levels));
    27	    for (k, v) in crate::styles::inspect_entries(s) {
    28	        m.insert(&k, v);
    29	    }
    30	    Value::Obj(m)
    31	}
    32	
    33	pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    34	    let pr = &s.project;
    35	    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    36	    let mut out = Vec::new();
    37	    for (id, e) in &pr.elements {
    38	        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
    39	        if let Some(want) = &cat {
    40	            if c != want {
    41	                continue;
    42	            }
    43	        }
    44	        let mut x = e.clone();
    45	        x.set("id", Value::u(*id));
    46	        if c == "level" {
    47	            x.set("computation_height", Value::f(1200.0));
    48	        }
    49	        if c == "pointcloud" {
    50	            crate::cloud::element_view(pr, &mut x);
    51	        }
    52	        out.push(x);
    53	    }
    54	    let n = out.len();
    55	    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
    56	}
     1	//! Scripts: one `id {json}` per line; blank lines and `#` comments are passed over.
     2	
     3	use crate::json::Value;
     4	
     5	pub struct Line {
     6	    pub line: usize,
     7	    pub id: String,
     8	    pub params: Value,
     9	}
    10	
    11	/// Parses a whole script before anything runs, so a bad line stops it at once.
    12	pub fn parse(text: &str) -> Result<Vec<Line>, String> {
    13	    let mut out = Vec::new();
    14	    for (n, raw) in text.lines().enumerate() {
    15	        let t = raw.trim();
    16	        if t.is_empty() || t.starts_with('#') {
    17	            continue;
    18	        }
    19	        let (id, rest) = match t.find(char::is_whitespace) {
    20	            Some(i) => (&t[..i], t[i..].trim()),
    21	            None => (t, ""),
    22	        };
    23	        let params = if rest.is_empty() {
    24	            Value::obj()
    25	        } else {
    26	            match crate::json::parse(rest) {
    27	                Ok(v) => v,
    28	                Err(e) => return Err(format!("line {}: bad JSON after `{}`: {}", n + 1, id, e)),
    29	            }
    30	        };
    31	        out.push(Line { line: n + 1, id: id.to_string(), params });
    32	    }
    33	    Ok(out)
    34	}
     1	//! Common lookups on the model: levels, elements by id or GUID.
     2	
     3	use crate::json::Value;
     4	use crate::project::Project;
     5	
     6	/// Levels from the lowest up (ties by id).
     7	pub fn levels(pr: &Project) -> Vec<u64> {
     8	    crate::commands::basic::level_ids_sorted(pr)
     9	}
    10	
    11	pub fn elev(pr: &Project, level: u64) -> f64 {
    12	    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
    13	}
    14	
    15	pub fn name(pr: &Project, id: u64) -> String {
    16	    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
    17	}
    18	
    19	/// The lowest level, where commands go without one.
    20	pub fn default_level(pr: &Project) -> Option<u64> {
    21	    levels(pr).first().copied()
    22	}
    23	
    24	/// The next level up from one, if any.
    25	pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    26	    let ls = levels(pr);
    27	    let i = ls.iter().position(|l| *l == level)?;
    28	    ls.get(i + 1).copied()
    29	}
    30	
    31	/// An element by its id (a number or a string of one) or its GUID.
    32	pub fn find(pr: &Project, v: &Value) -> Option<u64> {
    33	    match v {
    34	        Value::Num(_) => {
    35	            let id = crate::commands::params::id_of(v)?;
    36	            if pr.elements.contains_key(&id) {
    37	                Some(id)
    38	            } else {
    39	                None
    40	            }
    41	        }
    42	        Value::Str(s) => {
    43	            let t = s.trim();
    44	            if let Ok(id) = t.parse::<u64>() {
    45	                return if pr.elements.contains_key(&id) { Some(id) } else { None };
    46	            }
    47	            let g = normalize_guid(t)?;
    48	            pr.find_guid(&g)
    49	        }
    50	        _ => None,
    51	    }
    52	}
    53	
    54	/// A GUID as the model keeps it (lowercase, hyphenated), from one with or without braces and dashes.
    55	pub fn normalize_guid(s: &str) -> Option<String> {
    56	    let t = s.trim().trim_start_matches('{').trim_end_matches('}');
    57	    let hex: String = t.chars().filter(|c| *c != '-').collect();
    58	    if hex.len() != 32 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
    59	        return None;
    60	    }
    61	    let h = hex.to_lowercase();
    62	    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
    63	}
    64	
    65	/// A level (or a plan view, whose level it is) given by name, id or GUID.
    66	pub fn resolve_level(pr: &Project, cmd: &str, key: &str, v: &Value) -> Result<u64, String> {
    67	    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    68	    match v {
    69	        Value::Num(_) => {
    70	            let id = find(pr, v).ok_or_else(not)?;
    71	            level_of_view(pr, id).ok_or_else(not)
    72	        }
    73	        Value::Str(s) => {
    74	            if let Some(id) = find(pr, v) {
    75	                return level_of_view(pr, id).ok_or_else(not);
    76	            }
    77	            if s.trim().parse::<u64>().is_ok() || normalize_guid(s).is_some() {
    78	                return Err(not());
    79	            }
    80	            for id in levels(pr) {
    81	                if name(pr, id) == *s {
    82	                    return Ok(id);
    83	                }
    84	            }
    85	            for id in pr.ids_of("planview") {
    86	                if name(pr, id) == *s {
    87	                    if let Some(l) = level_of_view(pr, id) {
    88	                        return Ok(l);
    89	                    }
    90	                }
    91	            }
    92	            let names: Vec<String> = levels(pr).iter().map(|l| name(pr, *l)).collect();
    93	            Err(format!(
    94	                "{}: no level or plan view named `{}` (the levels are: {})",
    95	                cmd,
    96	                s,
    97	                names.join(", ")
    98	            ))
    99	        }
   100	        _ => Err(not()),
   101	    }
   102	}
   103	
   104	/// The level of a level, or of a plan view.
   105	pub fn level_of_view(pr: &Project, id: u64) -> Option<u64> {
   106	    match pr.category(id)? {
   107	        "level" => Some(id),
   108	        "planview" => {
   109	            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
   110	            pr.find_guid(&g)
   111	        }
   112	        _ => None,
   113	    }
   114	}
   115	
   116	/// A level from the params' `key`, else the lowest.
   117	pub fn level_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> Result<u64, String> {
   118	    match crate::commands::params::get(p, key) {
   119	        Some(v) => resolve_level(pr, cmd, key, v),
   120	        None => default_level(pr).ok_or_else(|| format!("{}: the project has no level", cmd)),
   121	    }
   122	}
"}

