   195	                    if let Some(Value::Num(n)) = m.get("id") {
   196	                        let x = n.as_f64();
   197	                        if x >= 900000.0 && x < 1_000_000.0 {
   198	                            *low = (*low).min(x as u64);
   199	                        }
   200	                    }
   201	                    for (_, x) in &m.items {
   202	                        scan(x, low);
   203	                    }
   204	                }
   205	                Value::Arr(a) => a.iter().for_each(|x| scan(x, low)),
   206	                _ => {}
   207	            }
   208	        }
