1: //! Reinforcement presets: `reinforcement_preset`.
2: //!
3: //! The file keeps them in `reinforcement` (left out while there are none), each by name in name
4: //! order: its `kind` and the `params` `reinforce` takes for it, as given (only their names are
5: //! checked against the kind); the library names each (`reinforcement-preset`).
6: 
7: use super::common::*;
8: use crate::json::Value;
9: use crate::project::Project;
10: use crate::session::Session;
11: 
12: pub const SECTION: &str = "reinforcement";
13: const LIB: &str = "reinforcement-preset";
14: pub const KINDS: &[&str] = &["beam", "column", "footing", "floor"];
15: 
16: /// The parameters of `reinforce` a preset of a kind may hold.
17: pub fn params_of(kind: &str) -> &'static [&'static str] {
18:     match kind {
19:         "beam" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top", "stirrup", "skin", "anchor"],
20:         "column" => &["cover", "grade", "grade_stirrup", "clearance", "bars", "stirrup", "ties", "anchor"],
21:         "footing" => &["cover", "grade", "grade_stirrup", "clearance", "mesh"],
22:         "floor" => &["cover", "grade", "grade_stirrup", "clearance", "bottom", "top"],
23:         _ => &[],
24:     }
25: }
26: 
27: /// A preset by its name or its GUID: its kind and its params, for `reinforce {preset}`.
28: pub fn find(pr: &Project, name: &str) -> Option<(String, Value)> {
29:     let name = super::electrical::resolve(pr, LIB, name.trim());
30:     let e = pr.section(SECTION)?.get(&name)?;
31:     Some((name, e.clone()))
32: }
33: 
34: /// A preset as the model holds it: of a kind, holding only what `reinforce` takes for that kind.
35: fn check_preset(name: &str, kind: &str, params: &Value) -> R<()> {
36:     let what = format!("reinforcement preset `{}`", name);
37:     if !KINDS.contains(&kind) {
38:         return Err(format!("{}: `kind` is one of {}, not `{}`", what, KINDS.join(", "), kind));
39:     }
40:     let allowed = params_of(kind);
41:     if let Some(m) = params.as_obj() {
42:         let mut keys: Vec<&String> = m.keys().collect();
43:         keys.sort();
44:         for k in keys {
45:             if !allowed.contains(&k.as_str()) {
46:                 return Err(format!("{}: `{}` isn't a parameter of a {}: {}", what, k, kind, allowed.join(", ")));
47:             }
48:         }
49:     }
50:     Ok(())
51: }
52: 
53: /// The model rules of reinforcement presets, in name order.
54: pub fn check(pr: &Project) -> R<()> {
55:     let mut presets: Vec<(String, Value)> = section(pr, SECTION).items;
56:     presets.sort_by(|a, b| a.0.cmp(&b.0));
57:     for (n, e) in &presets {
58:         let kind = e.get("kind").and_then(|k| k.as_str()).unwrap_or("");
59:         check_preset(n, kind, e.get("params").unwrap_or(&Value::Null))?;
60:     }
61:     Ok(())
62: }
63: 
64: pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
65:     let _ = cid;
66:     const CMD: &str = "reinforcement_preset";
67:     check_keys(p, CMD, &["name", "kind", "params", "rename", "delete"])?;
68:     let pr = &mut s.project;
69:     let Some(name) = opt_name(p, CMD, "name")? else {
70:         return Ok(jobj! {"presets" => Value::Obj(section(pr, SECTION))});
71:     };
72:     let name = super::electrical::resolve(pr, LIB, &name);
73:     let existing = pr.section(SECTION).and_then(|m| m.get(&name)).cloned();
74:     if opt_bool(p, CMD, "delete")? == Some(true) {
75:         if existing.is_none() {
76:             return Err(format!("{}: there's no reinforcement preset `{}`", CMD, name));
77:         }
78:         let sec = pr.section_mut(SECTION);
79:         sec.remove(&name);
80:         if sec.is_empty() {
81:             pr.remove_top(SECTION);
82:         }
83:         lib_remove(pr, LIB, &name);
84:         super::mark_step();
85:         return Ok(jobj! {"deleted" => name});
86:     }
87:     let rename = opt_name(p, CMD, "rename")?;
88:     let new = existing.is_none();
89:     let kind = crate::commands::params::opt_text(p, CMD, "kind")?;
90:     if kind.is_none() && new {
91:         return Err(format!("{}: `kind` (beam, column, footing, floor) is required for a new preset", CMD));
92:     }
93:     let params = match p.get("params") {
94:         None | Some(Value::Null) => None,
95:         Some(v @ Value::Obj(_)) => Some(v.clone().sorted()),
96:         Some(v) => {
97:             return Err(format!("{}: `params` must be an object of reinforce's parameters, got {}", CMD, v.to_compact()))
98:         }
99:     };
100:     if params.is_none() && new {
101:         return Err(format!("{}: `params` {{…}} is required for a new preset", CMD));
102:     }
103:     let target = rename.unwrap_or_else(|| name.clone());
104:     if target != name && pr.section(SECTION).map(|m| m.contains(&target)).unwrap_or(false) {
105:         return Err(format!("{}: there's already a reinforcement preset `{}`", CMD, target));
106:     }
107:     let old = existing.clone().unwrap_or_else(Value::obj);
108:     let kind = kind.or_else(|| old.get("kind").and_then(|k| k.as_str()).map(|k| k.to_string())).unwrap_or_default();
109:     let params = params.or_else(|| old.get("params").cloned()).unwrap_or_else(Value::obj);
110:     check_preset(&target, &kind, &params).map_err(|e| format!("{}: {}", CMD, e))?;
111:     let v = jobj! {"kind" => kind, "params" => params};
112:     {
113:         let sec = pr.section_mut(SECTION);
114:         if target != name {
115:             sec.remove(&name);
116:         }
117:         sec.insert_sorted(&target, v.clone());
118:     }
119:     if existing.is_some() {
120:         if target != name {
121:             lib_rename(pr, LIB, &name, &target);
122:         }
123:     } else {
124:         lib_ensure(pr, LIB, &target);
125:     }
126:     super::mark_step();
127:     Ok(jobj! {"name" => target, "preset" => v})
128: }

