27: /// A preset by its name or its GUID: its kind and its params, for `reinforce {preset}`.
28: pub fn find(pr: &Project, name: &str) -> Option<(String, Value)> {
29:     let name = super::electrical::resolve(pr, LIB, name.trim());
30:     let e = pr.section(SECTION)?.get(&name)?;
31:     Some((name, e.clone()))
32: }
33: 
34: /// A preset as the model holds it: of a kind, holding only what `reinforce` takes for that kind.
35: fn check_preset(name: &str, kind: &str, params: &Value) -> R<()> {
36:     let what = format!("reinforcement preset `{}`", name);
37:     if !KINDS.contains(&kind) {
38:         return Err(format!("{}: `kind` is one of {}, not `{}`", what, KINDS.join(", "), kind));
39:     }
40:     let allowed = params_of(kind);
41:     if let Some(m) = params.as_obj() {
42:         let mut keys: Vec<&String> = m.keys().collect();
43:         keys.sort();
44:         for k in keys {
45:             if !allowed.contains(&k.as_str()) {
46:                 return Err(format!("{}: `{}` isn't a parameter of a {}: {}", what, k, kind, allowed.join(", ")));
47:             }
48:         }
49:     }
50:     Ok(())
51: }
52: 
53: /// The model rules of reinforcement presets, in name order.
54: pub fn check(pr: &Project) -> R<()> {
55:     let mut presets: Vec<(String, Value)> = section(pr, SECTION).items;
56:     presets.sort_by(|a, b| a.0.cmp(&b.0));
57:     for (n, e) in &presets {
58:         let kind = e.get("kind").and_then(|k| k.as_str()).unwrap_or("");
59:         check_preset(n, kind, e.get("params").unwrap_or(&Value::Null))?;
60:     }
61:     Ok(())
62: }
