64: pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
65:     let _ = cid;
66:     const CMD: &str = "reinforcement_preset";
67:     check_keys(p, CMD, &["name", "kind", "params", "rename", "delete"])?;
68:     let pr = &mut s.project;
69:     let Some(name) = opt_name(p, CMD, "name")? else {
70:         return Ok(jobj! {"presets" => Value::Obj(section(pr, SECTION))});
71:     };
72:     let name = super::electrical::resolve(pr, LIB, &name);
73:     let existing = pr.section(SECTION).and_then(|m| m.get(&name)).cloned();
74:     if opt_bool(p, CMD, "delete")? == Some(true) {
75:         if existing.is_none() {
76:             return Err(format!("{}: there's no reinforcement preset `{}`", CMD, name));
77:         }
78:         let sec = pr.section_mut(SECTION);
79:         sec.remove(&name);
80:         if sec.is_empty() {
81:             pr.remove_top(SECTION);
82:         }
83:         lib_remove(pr, LIB, &name);
84:         super::mark_step();
85:         return Ok(jobj! {"deleted" => name});
86:     }
87:     let rename = opt_name(p, CMD, "rename")?;
88:     let new = existing.is_none();
89:     let kind = crate::commands::params::opt_text(p, CMD, "kind")?;
90:     if kind.is_none() && new {
91:         return Err(format!("{}: `kind` (beam, column, footing, floor) is required for a new preset", CMD));
92:     }
93:     let params = match p.get("params") {
94:         None | Some(Value::Null) => None,
95:         Some(v @ Value::Obj(_)) => Some(v.clone().sorted()),
96:         Some(v) => {
97:             return Err(format!("{}: `params` must be an object of reinforce's parameters, got {}", CMD, v.to_compact()))
98:         }
99:     };
100:     if params.is_none() && new {
101:         return Err(format!("{}: `params` {{…}} is required for a new preset", CMD));
102:     }
103:     let target = rename.unwrap_or_else(|| name.clone());
104:     if target != name && pr.section(SECTION).map(|m| m.contains(&target)).unwrap_or(false) {
105:         return Err(format!("{}: there's already a reinforcement preset `{}`", CMD, target));
106:     }
107:     let old = existing.clone().unwrap_or_else(Value::obj);
108:     let kind = kind.or_else(|| old.get("kind").and_then(|k| k.as_str()).map(|k| k.to_string())).unwrap_or_default();
109:     let params = params.or_else(|| old.get("params").cloned()).unwrap_or_else(Value::obj);
110:     check_preset(&target, &kind, &params).map_err(|e| format!("{}: {}", CMD, e))?;
111:     let v = jobj! {"kind" => kind, "params" => params};
112:     {
113:         let sec = pr.section_mut(SECTION);
114:         if target != name {
115:             sec.remove(&name);
116:         }
117:         sec.insert_sorted(&target, v.clone());
118:     }
119:     if existing.is_some() {
120:         if target != name {
121:             lib_rename(pr, LIB, &name, &target);
122:         }
123:     } else {
124:         lib_ensure(pr, LIB, &target);
125:     }
126:     super::mark_step();
127:     Ok(jobj! {"name" => target, "preset" => v})
128: }
