    71	
    72	    pub fn from_value(v: Value) -> Project {
    73	        let mut doc = match v {
    74	            Value::Obj(m) => m,
    75	            _ => Map::new(),
    76	        };
    77	        let mut elements = BTreeMap::new();
    78	        let mut library = BTreeMap::new();
    79	        if let Some(Value::Obj(m)) = doc.get_mut("elements").map(std::mem::take) {
