    89	                    library.insert(id, e);
    90	                }
    91	            }
    92	        }
    93	        if !doc.contains("elements") {
    94	            doc.insert("elements", Value::Null);
    95	        }
    96	        if !doc.contains("library") {
    97	            doc.insert("library", Value::Null);
    98	        }
