   100	    }
   101	
   102	    pub fn to_value(&self) -> Value {
   103	        let mut out = Map::new();
   104	        for (k, v) in &self.doc.items {
   105	            if k == "elements" {
   106	                let mut m = Map::new();
   107	                for (id, e) in &self.elements {
   108	                    m.items.push((id.to_string(), e.clone()));
   109	                }
   110	                out.items.push((k.clone(), Value::Obj(m)));
   111	            } else if k == "library" {
   112	                let mut m = Map::new();
   113	                for (id, e) in &self.library {
   114	                    m.items.push((id.to_string(), e.clone()));
   115	                }
   116	                out.items.push((k.clone(), Value::Obj(m)));
   117	            } else {
   118	                out.items.push((k.clone(), v.clone()));
   119	            }
   120	        }
