   126	    }
   127	
   128	    // ------------------------------------------------------------ top level
   129	
   130	    pub fn get(&self, k: &str) -> Option<&Value> {
   131	        self.doc.get(k)
   132	    }
   133	    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
