   141	    }
   142	    /// A section of the file (`types`, `materials`…), made where the canonical order puts it.
   143	    pub fn section_mut(&mut self, k: &str) -> &mut Map {
   144	        if !self.doc.contains(k) {
   145	            self.insert_top(k, Value::obj());
   146	        }
   147	        let v = self.doc.get_mut(k).unwrap();
   148	        if !matches!(v, Value::Obj(_)) {
   149	            *v = Value::obj();
   150	        }
   151	        v.as_obj_mut().unwrap()
   152	    }
   153	    pub fn section(&self, k: &str) -> Option<&Map> {
   154	        self.doc.get(k).and_then(|v| v.as_obj())
   155	    }
   156	    /// Inserts a top-level key at its place in the file's order.
   157	    pub fn insert_top(&mut self, k: &str, v: Value) {
   158	        if self.doc.contains(k) {
   159	            self.doc.insert(k, v);
   160	            return;
   161	        }
   162	        let order = TOP_ORDER;
   163	        let rank = |key: &str| order.iter().position(|o| *o == key).unwrap_or(usize::MAX);
   164	        let r = rank(k);
   165	        let pos = self.doc.items.iter().position(|(kk, _)| rank(kk) > r).unwrap_or(self.doc.items.len());
   166	        self.doc.items.insert(pos, (k.to_string(), v));
   167	    }
   168	    pub fn remove_top(&mut self, k: &str) {
