   170	    }
   171	
   172	    // ------------------------------------------------------------ ids
   173	
   174	    pub fn next_id(&self) -> u64 {
   175	        self.doc.get("next_id").and_then(|v| v.as_u64()).unwrap_or(100000)
   176	    }
   177	    pub fn alloc_id(&mut self) -> u64 {
   178	        let mut id = self.next_id();
   179	        while self.elements.contains_key(&id) {
   180	            id += 1;
   181	        }
   182	        self.doc.insert("next_id", Value::u(id + 1));
   183	        id
   184	    }
   185	
   186	    /// The lowest id the library and its parts use.
   187	    pub fn lowest_lib_id(&self) -> u64 {
   188	        let mut low = 1_000_000u64;
   189	        if let Some(k) = self.library.keys().next() {
   190	            low = low.min(*k);
   191	        }
   192	        fn scan(v: &Value, low: &mut u64) {
   193	            match v {
   194	                Value::Obj(m) => {
   195	                    if let Some(Value::Num(n)) = m.get("id") {
   196	                        let x = n.as_f64();
   197	                        if x >= 900000.0 && x < 1_000_000.0 {
   198	                            *low = (*low).min(x as u64);
   199	                        }
   200	                    }
   201	                    for (_, x) in &m.items {
   202	                        scan(x, low);
   203	                    }
   204	                }
   205	                Value::Arr(a) => a.iter().for_each(|x| scan(x, low)),
   206	                _ => {}
   207	            }
   208	        }
   209	        for (k, v) in &self.doc.items {
   210	            if k != "elements" && k != "library" {
   211	                scan(v, &mut low);
   212	            }
   213	        }
   214	        low
   215	    }
   216	    pub fn alloc_lib_id(&mut self) -> u64 {
