   248	    }
   249	
   250	    // ------------------------------------------------------------ library
   251	
   252	    pub fn lib_find_guid(&self, g: &str) -> Option<u64> {
   253	        self.library
   254	            .iter()
   255	            .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()) == Some(g))
   256	            .map(|(id, _)| *id)
