   266	    pub fn lib_guid(&self, kind: &str, name: &str) -> Option<String> {
   267	        let id = self.lib_find(kind, name)?;
   268	        self.library.get(&id).and_then(|e| e.get("guid")).and_then(|g| g.as_str()).map(|s| s.to_string())
   269	    }
   270	    /// The name of the library entry with this GUID.
   271	    pub fn lib_name(&self, g: &str) -> Option<String> {
