527	/// Decodes a PNG (whose signature has been seen) to 8-bit RGBA.
528	pub fn decode(data: &[u8]) -> Result<Image, Fail> {
529	    let mut r = Rd { d: data, pos: 8 };
530	    let mut info = Info::default();
531	    // the chunks before the image data
532	    let mut first_len;
533	    loop {
534	        let len = r.u32()?;
535	        let kind = r.tag()?;
536	        if info.header.is_none() && &kind != b"IHDR" {
537	            return err(format!("{} chunk appeared before IHDR chunk", chunk_debug(kind)));
538	        }
539	        if &kind == b"IDAT" {
540	            first_len = len;
541	            break;
542	        }
543	        let start = r.pos;
544	        let avail = data.len().saturating_sub(start);
545	        if (len as usize) > avail {
546	            return err(EOF);
547	        }
548	        let body = &data[start..start + len as usize];
549	        r.pos += len as usize;
550	        if len > 0 && parse_chunk(&mut info, kind, body)? {
