 41	fn cli(args: &[String], out: &mut impl Write) -> Result<(), String> {
 42	    let mut s = Session::new();
 43	    s.dwg = dwg_reader();
 44	    match args {
 45	        [cmd, rest @ ..] if cmd == "run" => {
 46	            let mut rest = rest.iter();
 47	            while let Some(arg) = rest.next() {
 48	                let mut value = || rest.next().ok_or_else(|| format!("{arg} needs a value\n\n{USAGE}"));
 49	                let results = match arg.as_str() {
 50	                    "--sample" => s.script(SAMPLE).map(|_| Vec::new())?,
 51	                    "--highrise" => vec![s.execute("highrise", &json!({}))?],
 52	                    "--cmd" => s.script(value()?)?,
 53	                    "--script" => {
 54	                        let path = value()?;
 55	                        s.script(&std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?)?
 56	                    }
 57	                    "--save" => vec![s.execute("save", &json!({ "path": value()? }))?],
 58	                    flag if flag.starts_with("--") => return Err(format!("unknown option `{flag}`\n\n{USAGE}")),
 59	                    file if revit::is_revit(file) => vec![revit::open(&mut s, file)?],
 60	                    file => vec![s.execute("open", &json!({ "path": file }))?],
 61	                };
 62	                for r in results.iter().filter(|r| !r.is_null()) {
 63	                    print(out, r)?;
 64	                }
 65	            }
 66	            Ok(())
 67	        }
 68	        [cmd, file] if cmd == "info" && revit::is_revit(file) => print_pretty(out, &revit::info(file)?),
 69	        [cmd, file] if cmd == "info" => {
 70	            s.execute("open", &json!({ "path": file }))?;
 71	            print_pretty(out, &s.execute("inspect", &json!({}))?)
 72	        }
 73	        [cmd, from, to] if cmd == "convert" => {
 74	            if revit::is_revit(from) {
 75	                revit::open(&mut s, from)?;
 76	            } else {
 77	                s.execute("open", &json!({ "path": from }))?;
 78	            }
 79	            print(out, &s.execute("save", &json!({ "path": to }))?)
 80	        }
