102	fn mcp_args(args: &[String]) -> Result<McpArgs, String> {
103	    let mut a = McpArgs::default();
104	    let mut rest = args.iter().peekable();
105	    while let Some(arg) = rest.next() {
106	        match arg.as_str() {
107	            "--read-only" => a.read_only = true,
108	            "--connect" if a.connect.is_none() => {
109	                let port = rest.next_if(|p| !p.starts_with("--"));
110	                a.connect = Some(port.map(|p| p.parse().map_err(|_| format!("`{p}` is not a port: a number up to 65535"))).transpose()?);
111	            }
112	            flag if flag.starts_with('-') => return Err(format!("`{flag}`: {MCP_USAGE}")),
113	            file if a.file.is_none() => a.file = Some(file.to_string()),
114	            _ => return Err(MCP_USAGE.into()),
115	        }
116	    }
117	    if a.connect.is_some() && a.file.is_some() {
118	        return Err(format!("a window has its own project: --connect takes no FILE ({MCP_USAGE})"));
119	    }
120	    Ok(a)
121	}
