124	fn mcp_server(args: McpArgs) -> Result<mcp::Server, String> {
125	    let mut server = match args.connect {
126	        Some(port) => mcp::Server::attached(window::Window::connect(port)?),
127	        None => mcp::Server::new(),
128	    };
129	    if let Some(file) = &args.file {
